import{_ as i,o as a,c as n,a2 as s}from"./chunks/framework.CuEaBji2.js";const g=JSON.parse('{"title":"Agent generation 运维","description":"","frontmatter":{},"headers":[],"relativePath":"operations/agent-generation.md","filePath":"operations/agent-generation.md","lastUpdated":1785415935000}'),t={name:"operations/agent-generation.md"};function o(d,e,l,r,p,c){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="agent-generation-运维" tabindex="-1">Agent generation 运维 <a class="header-anchor" href="#agent-generation-运维" aria-label="Permalink to &quot;Agent generation 运维&quot;">​</a></h1><h2 id="状态语义" tabindex="-1">状态语义 <a class="header-anchor" href="#状态语义" aria-label="Permalink to &quot;状态语义&quot;">​</a></h2><p>配置保存、runtime 生效和旧会话排空是三个独立时点：</p><ul><li><code>saved / pending</code>：数据库和 immutable snapshot 已提交，API 已返回 202，runtime 尚未 cutover。</li><li><code>applying</code>：Agent 已确认开始 prepare；一次真实 attempt 从此时计时。</li><li><code>applied + draining</code>：新 generation 已接管新连接，<code>applied_revision</code> 已更新；旧 generation 仅服务已有会话。</li><li><code>applied + drained</code>：旧 generation 已自然归零并释放。</li><li><code>applied + forced</code>：旧 generation 达到 drain timeout 或 generation 上限后被强制释放。</li><li><code>failed</code>：desired 配置保留，last-known-good generation 继续运行，可显式 retry 或 rollback。</li><li><code>superseded</code>：更高 desired revision 已取代旧 pending/applying 工作；旧 revision 不得覆盖新 revision。</li></ul><p>普通修改和新增会优雅排空旧会话；delete 或 <code>enabled=false</code> 在新 generation ready 后立即关闭受影响旧会话。HTTP/1.1、HTTP/2、HTTP/3、WebSocket、L4 TCP/UDP 与 Relay 都遵守 generation ownership；UDP 按旧五元组/association 继续旧路径，新五元组进入 active generation。</p><p>同一 Agent 串行 apply，不同 Agent 可并行。跨 Agent dependency DAG 只保证依赖顺序和每个 Agent 原子性；部分失败保留已成功节点，并把 operation 标记为 <code>degraded</code>，不会自动补偿回滚。</p><h2 id="timeout-配置" tabindex="-1">Timeout 配置 <a class="header-anchor" href="#timeout-配置" aria-label="Permalink to &quot;Timeout 配置&quot;">​</a></h2><p>全局默认值：</p><div class="language-env vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NRE_REVISION_APPLY_TIMEOUT=1m</span></span>
<span class="line"><span>NRE_REVISION_DRAIN_TIMEOUT=10m</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>按 Agent 覆盖使用单行 JSON；每个缺失字段回落到全局值：</p><div class="language-env vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NRE_REVISION_AGENT_TIMEOUT_OVERRIDES={&quot;edge-a&quot;:{&quot;apply_timeout&quot;:&quot;45s&quot;},&quot;edge-b&quot;:{&quot;drain_timeout&quot;:&quot;15m&quot;},&quot;local&quot;:{&quot;apply_timeout&quot;:&quot;2m&quot;,&quot;drain_timeout&quot;:&quot;8m&quot;}}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>键必须是非空 Agent ID，值只能包含 <code>apply_timeout</code>、<code>drain_timeout</code>，duration 必须为正的 Go duration 字符串。malformed JSON、未知字段、null、非字符串或非正 duration 会阻止 control plane 启动，不会静默使用默认值。</p><p>Timeout 在 revision 创建时按“Agent 字段覆盖 -&gt; global”解析并以秒固化。之后修改环境变量只影响新 revision，不会改变正在 applying/draining 的 generation。同一 Agent/module 最多保留 2 个 draining generation；创建第三个时强制释放最老一代并记录 <code>generation_limit</code>。</p><h2 id="监控与排障" tabindex="-1">监控与排障 <a class="header-anchor" href="#监控与排障" aria-label="Permalink to &quot;监控与排障&quot;">​</a></h2><p>Panel token 保护的 Prometheus 文本端点：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;X-Panel-Token: &lt;panel-token&gt;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/panel-api/metrics</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Control plane 指标族：</p><ul><li><code>nre_revision_queue_total</code> / <code>nre_revision_queue_duration_seconds_sum</code></li><li><code>nre_revision_apply_total</code> / <code>nre_revision_apply_duration_seconds_sum</code></li><li><code>nre_generation_drain_total</code> / <code>nre_generation_drain_duration_seconds_sum</code></li><li><code>nre_generation_cutover_total</code> / <code>nre_generation_cutover_duration_seconds_sum</code></li><li><code>nre_hot_restart_upgrade_total</code> / <code>nre_hot_restart_upgrade_duration_seconds_sum</code></li></ul><p>Embedded Agent 还暴露对应的 <code>nre_agent_revision_apply</code>、<code>nre_agent_generation_drain</code>、<code>nre_agent_generation_cutover</code>、<code>nre_agent_hot_restart_upgrade</code> 指标族。唯一 label 是有限枚举 <code>outcome</code>；<code>agent_id</code>、revision、generation、operation、attempt 和 lease 不作为 metric label，避免高基数。</p><p>详细关联写入结构化日志字段 <code>operation_id</code>、<code>agent_id</code>、<code>revision</code>、<code>generation_id</code>、<code>attempt</code>、<code>duration_ms</code>。token、secret、private key、certificate material、payload 和 <code>lease_id</code> 会被过滤。排障顺序：</p><ol><li>从 202 envelope 记录 <code>operation_id</code>、Agent revision 和 <code>status_url</code>。</li><li>查询 operation，确认是否 <code>blocked_by</code> dependency、<code>failed</code>、<code>superseded</code> 或 <code>degraded</code>。</li><li>查询 Agent revision 的 attempts/generations，区分 apply timeout 与 drain timeout。</li><li>用 <code>/revision-events?operation_id=...</code> 从最后 cursor 续读，再按相同 correlation 字段检索日志。</li><li>failed 时先修复 <code>error_code/error_message</code> 指向的问题，再 retry；需要恢复配置内容时用 rollback 创建新 revision。</li></ol><h2 id="retention-与恢复" tabindex="-1">Retention 与恢复 <a class="header-anchor" href="#retention-与恢复" aria-label="Permalink to &quot;Retention 与恢复&quot;">​</a></h2><p>Revision ledger 持久化 pending/applying/applied/failed、attempt、generation 和事件。Control plane 重启后只恢复每个 Agent 的最新 desired 工作，遗留 applying 会按 lease/attempt 规则重新协调；Agent 离线不消耗 attempt。</p><p>Retention 启动即运行、之后每 24 小时运行：保留每 Agent 最近 30 天且最多 500 版，并 pin 当前 desired/applied、last-known-good 和 active/draining 引用；幂等键保留 24 小时。日志前缀 <code>[revision-retention]</code> 表示本轮维护失败，HTTP 和 apply 服务继续运行，下一周期重试。</p><h2 id="迁移检查" tabindex="-1">迁移检查 <a class="header-anchor" href="#迁移检查" aria-label="Permalink to &quot;迁移检查&quot;">​</a></h2><ul><li>升级前备份 <code>panel/data/</code> 或外部数据库，并保留当前 Agent 二进制。</li><li>先确认所有远端 Agent 能用 <code>X-Agent-Token</code> 调用 revision pull/start/report；旧同步写响应不能再作为“已生效”证据。</li><li>升级 control plane 后检查现有 Agent 已生成 baseline desired/applied pointer，再提交一个低风险修改。</li><li>验证写请求返回 202、operation 最终 applied、<code>applied_revision</code> 前进；有长连接时允许暂时显示 draining。</li><li>独立 Agent 自更新前按 <a href="./agent-hot-upgrade">热升级运维</a> 核对平台、package digest 和回退指针。</li></ul><p>发布验证命令：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel/backend-go</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go-agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/generation-soak</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TestGenerationMatrix</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/generation-soak</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TestGenerationSoak100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div>`,28)])])}const u=i(t,[["render",o]]);export{g as __pageData,u as default};
